// MTCTCE course structure and question banks. Modules follow the official MTCTCE outline and both
// parts of the course slides: DNS, DHCP, web proxy, packet flow, firewall and attacks, NAT and
// mangle, QoS (queue types, simple queues, HTB and queue trees). Lessons teach RouterOS 7, with
// the RouterOS 6 differences as side notes.

import { T } from '../i18n.js'

// [question EN, question RU, options EN, options RU, correct index, explanation EN, explanation RU]
const Q = (rows) => rows.map(([qe, qr, oe, or, a, ee, er]) => ({ q: T(qe, qr), o: T(oe, or), a, e: T(ee, er) }))

